import { BOHR_TO_ANGSTROM } from '@matterlab/core';
import { describe, expect, it } from 'vitest';
import { STO3G_SOURCE } from '../src/basis/sto3g.generated';
import { runRhf, virialRatio } from '../src/index';
import type { ScfResult } from '../src/index';
import { pyscfFixture, toInput } from './helpers/pyscf';
import type { PyscfMolecule } from './helpers/pyscf';
import { validationReporter } from './helpers/report';

/**
 * RHF/STO-3G total energies, orbital energies, Mulliken charges and dipole moments against PySCF
 * (fixture generated by tools/gen_reference.py; the PySCF version is recorded in the fixture).
 * PySCF was given the same Basis Set Exchange snapshot and the same coordinates as the engine, so
 * the two programs solve exactly the same problem with independent integral and SCF codes.
 *
 * Target tolerances: total energy 1e-6 hartree, orbital energies 1e-5 hartree, Mulliken charges
 * 1e-4 e, dipole components 1e-4 e a0.
 */

const record = validationReporter('pyscf-scf');
const fixture = pyscfFixture();

const ENERGY_TOLERANCE = 1e-6;
const ORBITAL_ENERGY_TOLERANCE = 1e-5;
const CHARGE_TOLERANCE = 1e-4;
const DIPOLE_TOLERANCE = 1e-4;

function maxAbs(a: ArrayLike<number>, b: ArrayLike<number>): number {
  let largest = 0;
  for (let i = 0; i < a.length; i++) largest = Math.max(largest, Math.abs(a[i] - b[i]));
  return largest;
}

function compare(result: ScfResult, reference: PyscfMolecule) {
  return {
    totalEnergy: Math.abs(result.energy.total - reference.energy.total),
    nuclearRepulsion: Math.abs(result.energy.nuclearRepulsion - reference.energy.nuclearRepulsion),
    kinetic: Math.abs(result.energy.kinetic - reference.energy.kinetic),
    nuclearAttraction: Math.abs(result.energy.nuclearAttraction - reference.energy.nuclearAttraction),
    twoElectron: Math.abs(result.energy.twoElectron - reference.energy.twoElectron),
    orbitalEnergies: maxAbs(result.orbitalEnergies, reference.orbitalEnergies),
    mullikenCharges: maxAbs(result.mullikenCharges, reference.mullikenCharges),
    dipole: maxAbs(result.dipole.au, reference.dipoleAu),
  };
}

describe('the reference fixture', () => {
  it('was generated with the same basis-set snapshot and bohr constant the engine uses', () => {
    expect(fixture.basis.sha256).toBe(STO3G_SOURCE.sha256);
    expect(fixture.bohrToAngstrom).toBe(BOHR_TO_ANGSTROM);
    expect(fixture.versions.pyscf).toMatch(/^\d+\.\d+/);
    expect(fixture.molecules.every((m) => m.converged)).toBe(true);
  });

  it('covers the required molecules', () => {
    const names = new Set(fixture.molecules.map((m) => m.name));
    for (const required of [
      'H2', 'HeH+', 'LiH', 'H2O', 'NH3', 'CH4', 'HF', 'N2', 'CO', 'CO2', 'HCN', 'C2H4', 'C2H2', 'H2S', 'HCl', 'SiH4', 'PH3', 'NH4+', 'OH-', 'H2CO', 'C6H6',
    ]) {
      expect(names.has(required), required).toBe(true);
    }
  });
});

describe('RHF/STO-3G against PySCF with default convergence settings', () => {
  const rows: Record<string, unknown>[] = [];

  it.each(fixture.molecules.map((m) => [`${m.name} (${m.orientation})`, m] as const))('%s', (label, reference) => {
    const result = runRhf(toInput(reference));
    const deviation = compare(result, reference);
    rows.push({
      system: label,
      nBasis: result.nBasis,
      iterations: result.iterations.length,
      converged: result.converged,
      energy: result.energy.total,
      referenceEnergy: reference.energy.total,
      ...deviation,
      virialRatio: virialRatio(result),
      warnings: result.warnings,
      totalMs: result.timings.totalMs,
    });
    record('default-settings', { pyscf: fixture.versions.pyscf, generated: fixture.generated, rows });

    expect(result.converged).toBe(true);
    expect(result.warnings).toEqual([]);
    expect(result.nBasis).toBe(reference.nBasis);
    expect(result.nElectrons).toBe(reference.nElectrons);
    expect(result.nOccupied).toBe(reference.nOccupied);
    expect(result.dipole.originDependent).toBe(reference.charge !== 0);
    expect(deviation.nuclearRepulsion).toBeLessThan(1e-9);
    expect(deviation.totalEnergy).toBeLessThan(ENERGY_TOLERANCE);
    expect(deviation.orbitalEnergies).toBeLessThan(ORBITAL_ENERGY_TOLERANCE);
    expect(deviation.mullikenCharges).toBeLessThan(CHARGE_TOLERANCE);
    expect(deviation.dipole).toBeLessThan(DIPOLE_TOLERANCE);
    // Energy components are first order in the density error, so they get the looser property tolerance.
    expect(deviation.kinetic).toBeLessThan(1e-4);
    expect(deviation.nuclearAttraction).toBeLessThan(1e-4);
    expect(deviation.twoElectron).toBeLessThan(1e-4);
  });
});

describe('RHF/STO-3G against PySCF with tight convergence (1e-12 hartree, 1e-10 RMS density)', () => {
  const rows: Record<string, unknown>[] = [];

  it.each(fixture.molecules.map((m) => [`${m.name} (${m.orientation})`, m] as const))('%s', (label, reference) => {
    const result = runRhf(toInput(reference), { energyTolerance: 1e-12, densityTolerance: 1e-10 });
    const deviation = compare(result, reference);
    rows.push({ system: label, iterations: result.iterations.length, ...deviation });
    record('tight-settings', { rows });
    expect(result.converged).toBe(true);
    // Both programs are converged far below the targets here, so the remaining differences are
    // those of the integral codes and of floating-point summation order.
    expect(deviation.totalEnergy).toBeLessThan(1e-9);
    expect(deviation.orbitalEnergies).toBeLessThan(1e-8);
    expect(deviation.mullikenCharges).toBeLessThan(1e-7);
    expect(deviation.dipole).toBeLessThan(1e-7);
  });
});
